package main

import (
	"bytes"
	"crypto/aes"
	"encoding/binary"
	"os"
	"path/filepath"
	"testing"
)

// syntheticFixture contains deterministic generated bytes, never a user's music.
// A valid NCM envelope exercises the conversion, queue and safe-cleanup tests in CI.
func syntheticFixture(t *testing.T) string {
	t.Helper()
	key := []byte("ci-synthetic-key")
	raw := append([]byte("neteasecloudmusic"), key...)
	pad := aes.BlockSize - len(raw)%aes.BlockSize
	raw = append(raw, bytes.Repeat([]byte{byte(pad)}, pad)...)
	block, err := aes.NewCipher([]byte("hzHRAmso5kInbaxW"))
	if err != nil {
		t.Fatal(err)
	}
	encryptedKey := make([]byte, len(raw))
	for i := 0; i < len(raw); i += aes.BlockSize {
		block.Encrypt(encryptedKey[i:i+aes.BlockSize], raw[i:i+aes.BlockSize])
	}
	for i := range encryptedKey {
		encryptedKey[i] ^= 0x64
	}
	var box [256]byte
	for i := range box {
		box[i] = byte(i)
	}
	var last byte
	for i := range box {
		swap := box[i]
		c := swap + last + key[i%len(key)]
		box[i], box[c] = box[c], swap
		last = c
	}
	// ID3 header and generated payload span multiple decryption buffers.
	audio := make([]byte, 600003)
	copy(audio, []byte{'I', 'D', '3', 3, 0, 0, 0, 0, 0, 0})
	for i := 10; i < len(audio); i++ {
		audio[i] = byte(i * 7)
	}
	for i := range audio {
		j := (i + 1) & 255
		audio[i] ^= box[(int(box[j])+int(box[(int(box[j])+j)&255]))&255]
	}
	var out bytes.Buffer
	out.WriteString("CTENFDAM")
	out.Write([]byte{0, 0})
	if err := binary.Write(&out, binary.LittleEndian, uint32(len(encryptedKey))); err != nil {
		t.Fatal(err)
	}
	out.Write(encryptedKey)
	out.Write(make([]byte, 17)) // metadata length, gap, cover frame/data lengths
	out.Write(audio)
	p := filepath.Join(t.TempDir(), "synthetic.ncm")
	if err := os.WriteFile(p, out.Bytes(), 0600); err != nil {
		t.Fatal(err)
	}
	return p
}
